#!/usr/bin/env python3
"""Render docs/parameters.md from nextflow_schema.json.

Run after editing the schema:  python3 scripts/render_parameters_doc.py
The test suite fails if docs/parameters.md is out of date.
"""

from __future__ import annotations

import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def render(schema: dict) -> str:
    lines = [
        "# Parameters",
        "",
        "<!-- Generated by scripts/render_parameters_doc.py from nextflow_schema.json. Do not edit. -->",
        "",
        "Parameters are passed to Nextflow as `--name value`. Reference paths are",
        "written to `conf/references.config` by the installer, and primers are",
        "maintained in `conf/primers.config`.",
        "",
    ]
    for group in schema["$defs"].values():
        lines += [f"## {group['title']}", ""]
        if group.get("description"):
            lines += [group["description"], ""]
        lines += ["| Parameter | Type | Default | Description |", "| --- | --- | --- | --- |"]
        required = set(group.get("required", []))
        for name, spec in group["properties"].items():
            kind = spec.get("type", "")
            if "enum" in spec:
                kind += " (" + ", ".join(f"`{value}`" for value in spec["enum"]) + ")"
            default = spec.get("default")
            default_text = "" if default in (None, "") else f"`{json.dumps(default).strip(chr(34))}`"
            label = f"`--{name}`" + (" (required)" if name in required else "")
            description = spec.get("description", "").replace("|", "\\|")
            lines.append(f"| {label} | {kind} | {default_text} | {description} |")
        lines.append("")
    return "\n".join(lines)


def main() -> int:
    schema = json.loads((ROOT / "nextflow_schema.json").read_text(encoding="utf-8"))
    target = ROOT / "docs" / "parameters.md"
    content = render(schema)
    if "--check" in sys.argv:
        if not target.is_file() or target.read_text(encoding="utf-8") != content:
            print(f"{target} is out of date; run {Path(__file__).name}", file=sys.stderr)
            return 1
        return 0
    target.write_text(content, encoding="utf-8")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
